"""Atelier 100, 3e tour : prix (slide 13). Trois idées vraiment différentes, sans icônes répétées."""
ITEMS = []
def V(name, desc, js='', css=''): return dict(name=name, desc=desc, js=js, css=css)
P = r"const cs=A.shapes(sl).filter(s=>s.dash&&s.w>150).sort((a,b)=>a.x-b.x);A.texts(sl).filter(t=>/💰/.test(t.text)).forEach(t=>t.el.style.visibility='hidden');const tx=A.texts(sl).filter(t=>/^\$/.test(t.text)).sort((a,b)=>a.x-b.x);"
ITEMS.append(dict(id='1', title="Prix : trois gammes, sans sacs d'argent", what="Tu veux autre chose que trois icônes ou des barres : la gamme de prix doit se voir dans la mise en page elle-même.",
  scope=[13], shot=13, fam='Prix', clip=None, mine='A', why="Les cartes qui « chauffent » du bleu au rose disent la montée en prix sans aucun symbole, et la flèche du haut prend tout son sens.",
  A=V('Cartes qui chauffent', "Plus d'icône : les trois cartes deviennent des aplats qui passent du bleu nuit au rose plein ; la plus chère est rose avec texte blanc.",
    P + r"const f=['#0E3D55','#5A2450','#FB0161'];cs.forEach((s,i)=>{s.p.removeAttribute('stroke-dasharray');s.p.setAttribute('stroke','none');s.p.setAttribute('fill',f[i])});A.texts(sl).filter(t=>t.x>540&&t.y>290).forEach(t=>A.color(t,'#fff'))"),
  B=V('Étiquettes de prix', "Le prix de chaque carte devient une vraie étiquette (forme d'étiquette avec son trou), de plus en plus grande et de plus en plus rose.",
    P + r"cs.forEach(s=>{s.p.removeAttribute('stroke-dasharray');s.p.setAttribute('stroke','#1E4558')});tx.forEach((t,i)=>{const p=t.el.querySelector('p');const price=p.textContent.trim();const w=104+i*14,h=32+i*3,c=['#33525F','#B8325F','#FB0161'][i];p.innerHTML=`<svg width='${w}' height='${h}' viewBox='0 0 ${w} ${h}' style='display:inline-block'><path d='M0 ${h/2} L${h/2} 0 H${w-6} a6 6 0 0 1 6 6 V${h-6} a6 6 0 0 1 -6 6 H${h/2} Z' fill='${c}'/><circle cx='${h/2+2}' cy='${h/2}' r='4' fill='#062A3C'/><text x='${(w+h/2)/2+4}' y='${h/2+5}' text-anchor='middle' font-family='Lexend' font-weight='700' font-size='${13+i*1.5}' fill='#fff'>${price}</text></svg>`;p.style.lineHeight='1';p.style.marginBottom='4px'})"),
  C=V('Escalier de prix', "Plus d'icône : les cartes montent comme des marches (la plus chère est la plus haute) et deviennent pleines ; la flèche suit la pente.",
    P + r"const ar=A.shapes(sl).find(s=>s.fill&&s.fill.toUpperCase()==='#FB0161'&&s.w>500);cs.forEach((s,i)=>{const dy=(1-i)*34;const R=sl.getBoundingClientRect();[...sl.querySelectorAll('.raw > *')].forEach(e=>{const b=e.getBoundingClientRect(),cx=b.left-R.left+b.width/2,cy=b.top-R.top+b.height/2;if(b.width<300&&cx>s.x&&cx<s.x+s.w&&cy>s.y-20&&cy<s.y+s.h+20)e.style.top=(parseFloat(e.style.top)+dy)+'px'});s.p.removeAttribute('stroke-dasharray');s.p.setAttribute('stroke','none');s.p.setAttribute('fill',['#0B3850','#0E3D55','#123F57'][i])});if(ar){ar.el.style.transformOrigin='left center';ar.el.style.transform='translateY(40px) rotate(-6deg)'}")))
